window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-66e885e72af45a2c"]={"versions": [{"id": "FIG-66e885e72af45a2c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des Metamodellausschnitts für Service-Aufrufe im Kontext des Behavior Modeling Tools (BMT). Das Diagramm spezifiziert die Integration von AUTOSAR-Server-Call-Punkten in Verhaltensmodelle von Software-Komponenten (Paket <code>Behavior Modeling</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Identifiable::ServerCall::ServerCallPoint</code>: Abstrakte Basisklasse für Server-Aufrufstellen im Metamodell, erbt von <code>Identifiable</code>.\n</li><li><code>ServerCall::SynchronousServerCallPoint</code>: Konkrete Spezialisierung von <code>ServerCallPoint</code> zur Repräsentation blockierender, synchroner Funktions- bzw. Serviceaufrufe.\n</li><li><code>ServerCall::AsynchronousServerCallPoint</code>: Konkrete Spezialisierung von <code>ServerCallPoint</code> zur Modellierung nicht-blockierender, asynchroner Serviceanfragen.\n</li><li><code>BM Software-Component</code>: Paket bzw. Modellelement (mit Herkunftskennzeichnung <code>(from Behavior Modeling)</code>), das über gerichtete Abhängigkeiten mit dem Stereotyp <code>«import»</code> auf die beiden Aufrufstellen <code>SynchronousServerCallPoint</code> und <code>AsynchronousServerCallPoint</code> zugreift. Zusätzlich existiert eine gestrichelte Assoziations-/Abhängigkeitslinie zur Basisklasse <code>ServerCallPoint</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionssequenz. Die Klassen bilden die metamodellierte Grundlage ab, mit der eine Verhaltensmodell-Komponente (<code>BM Software-Component</code>) entweder synchrone oder asynchrone Service-Aufrufe an Basissoftware-Dienste über die AUTOSAR RTE initiiert:</p>\n<ul class=\"fig-list\"><li>Bei Verwendung eines <code>SynchronousServerCallPoint</code> wartet das Verhaltensmodell auf die Beendigung des Service-Aufrufs und Rückgabewerte.\n</li><li>Bei Verwendung eines <code>AsynchronousServerCallPoint</code> wird der Aufruf angestoßen, ohne den weiteren Ablauf innerhalb der aufrufenden Komponente direkt zu blockieren.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler von Verhaltensmodellen (BMT-Werkzeugen und Modellierungs-Workflows) müssen sicherstellen, dass Serviceaufrufe an BSW-Dienste über die RTE semantisch korrekt typisiert werden. Software-Komponenten im Verhaltensmodell müssen explizit spezifizieren, ob ein synchroner oder asynchroner Interaktionsmechanismus genutzt wird, da dies die Task-Blockierung, RTE-Generierung und Schnittstellenverträge der BSW-Services bestimmt.</p>"}, {"id": "FIG-d947d8babaf62579", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des Metamodellausschnitts für Service-Aufrufe im Kontext des Behavior Modeling Tools (BMT). Das Diagramm spezifiziert die Integration von AUTOSAR-Server-Call-Punkten in Verhaltensmodelle von Software-Komponenten (Paket <code>Behavior Modeling</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Identifiable::ServerCall::ServerCallPoint</code>: Abstrakte Basisklasse für Server-Aufrufstellen im Metamodell, erbt von <code>Identifiable</code>.\n</li><li><code>ServerCall::SynchronousServerCallPoint</code>: Konkrete Spezialisierung von <code>ServerCallPoint</code> zur Repräsentation blockierender, synchroner Funktions- bzw. Serviceaufrufe.\n</li><li><code>ServerCall::AsynchronousServerCallPoint</code>: Konkrete Spezialisierung von <code>ServerCallPoint</code> zur Modellierung nicht-blockierender, asynchroner Serviceanfragen.\n</li><li><code>BM Software-Component</code>: Paket bzw. Modellelement (mit Herkunftskennzeichnung <code>(from Behavior Modeling)</code>), das über gerichtete Abhängigkeiten mit dem Stereotyp <code>«import»</code> auf die beiden Aufrufstellen <code>SynchronousServerCallPoint</code> und <code>AsynchronousServerCallPoint</code> zugreift. Zusätzlich existiert eine gestrichelte Assoziations-/Abhängigkeitslinie zur Basisklasse <code>ServerCallPoint</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionssequenz. Die Klassen bilden die metamodellierte Grundlage ab, mit der eine Verhaltensmodell-Komponente (<code>BM Software-Component</code>) entweder synchrone oder asynchrone Service-Aufrufe an Basissoftware-Dienste über die AUTOSAR RTE initiiert:</p>\n<ul class=\"fig-list\"><li>Bei Verwendung eines <code>SynchronousServerCallPoint</code> wartet das Verhaltensmodell auf die Beendigung des Service-Aufrufs und Rückgabewerte.\n</li><li>Bei Verwendung eines <code>AsynchronousServerCallPoint</code> wird der Aufruf angestoßen, ohne den weiteren Ablauf innerhalb der aufrufenden Komponente direkt zu blockieren.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler von Verhaltensmodellen (BMT-Werkzeugen und Modellierungs-Workflows) müssen sicherstellen, dass Serviceaufrufe an BSW-Dienste über die RTE semantisch korrekt typisiert werden. Software-Komponenten im Verhaltensmodell müssen explizit spezifizieren, ob ein synchroner oder asynchroner Interaktionsmechanismus genutzt wird, da dies die Task-Blockierung, RTE-Generierung und Schnittstellenverträge der BSW-Services bestimmt.</p>"}], "trans": [{"from": "FIG-66e885e72af45a2c", "to": "FIG-d947d8babaf62579", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
